# ============================================================
# DECORATORS
# ============================================================
# WHAT: A function that takes a function, adds behavior,
#        and returns a modified function.
# WHY:  Add functionality without modifying original code.
#        Follows Open/Closed Principle (SOLID).
# ANALOGY: Gift wrapping — the gift (function) stays the same,
#          but the wrapping (decorator) adds presentation.

import functools
import time
from typing import Any, Callable

# --- Basic Decorator ---
def my_decorator(func):
    @functools.wraps(func)  # Preserves original function metadata
    def wrapper(*args, **kwargs):
        print("Before function call")
        result = func(*args, **kwargs)
        print("After function call")
        return result
    return wrapper

@my_decorator  # Equivalent to: say_hello = my_decorator(say_hello)
def say_hello(name):
    """Says hello to someone."""
    return f"Hello, {name}!"

print(say_hello("Veera"))
print(say_hello.__name__)  # "say_hello" (preserved by @wraps)
print(say_hello.__doc__)   # "Says hello to someone."

# --- Decorator WITH Arguments ---
def repeat(times: int):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(times=3)
def greet(name):
    print(f"Hi {name}")

greet("Veera")  # Prints "Hi Veera" 3 times

# --- Timer Decorator (very common in interviews!) ---
def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} took {elapsed:.4f} seconds")
        return result
    return wrapper

# --- Retry Decorator ---
def retry(max_attempts: int = 3, delay: float = 1.0):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        raise
                    print(f"Attempt {attempt} failed: {e}. Retrying...")
                    time.sleep(delay)
        return wrapper
    return decorator

@retry(max_attempts=3, delay=0.5)
def fetch_data(url):
    import random
    if random.random() < 0.7:
        raise ConnectionError("Network error")
    return {"data": "success"}

# --- Cache/Memoize Decorator ---
def memoize(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

# Or use built-in:
@functools.lru_cache(maxsize=128)
def fibonacci(n):
    if n < 2: return n
    return fibonacci(n - 1) + fibonacci(n - 2)

# --- Class-based Decorator ---
class CountCalls:
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"{self.func.__name__} called {self.count} times")
        return self.func(*args, **kwargs)

@CountCalls
def process():
    pass

process()  # process called 1 times
process()  # process called 2 times

# --- Stacking Multiple Decorators ---
@timer
@retry(max_attempts=2, delay=0.1)
def important_task():
    print("Running task...")

# Equivalent to: important_task = timer(retry(...)(important_task))

# --- Decorator for Class Methods ---
def validate_positive(func):
    @functools.wraps(func)
    def wrapper(self, amount):
        if amount <= 0:
            raise ValueError(f"Amount must be positive, got {amount}")
        return func(self, amount)
    return wrapper

class Account:
    def __init__(self):
        self.balance = 0

    @validate_positive
    def deposit(self, amount):
        self.balance += amount
